InitScript:
AddBuff("SpecialBuff_HolyJudgementEngine",  "1");
Self.AddSummon("AnimationLib/神圣审判机关/十字", "十字");
Self.AddSummon("AnimationLib/神圣审判机关/花纹", "花纹");
Self.AddSummon("AnimationLib/神圣审判机关/表盘", "表盘");
Self.AddSummon("AnimationLib/神圣审判机关/眼睛", "眼睛");
Self.AddSummon("AnimationLib/神圣审判机关/指针", "指针");
// =====动画=====
Self.FindSummon("花纹").transform.DORotate(new Vector3(0, 0, 360), 16f, RotateMode.FastBeyond360)
            .SetLoops(-1, LoopType.Restart)
            .SetEase(Ease.Linear);

Self.FindSummon("表盘").transform.DORotate(new Vector3(0, 0, -360), 16f, RotateMode.FastBeyond360)
            .SetLoops(-1, LoopType.Restart)
            .SetEase(Ease.Linear);
